tools.example:
net = NetChain[{LinearLayer[32], Ramp, LinearLayer[3], SoftmaxLayer[]},
  "Input" -> 4, "Output" -> NetDecoder[{"Class", {"a", "b", "c"}}]];
net[{1., 2., 3., 4.}]

data = Table[x -> Sin[x], {x, RandomReal[{0, 2 Pi}, 500]}];
net = NetChain[{LinearLayer[32], Tanh, LinearLayer[1]}, "Input" -> "Scalar",
  "Output" -> "Scalar"];
trained = NetTrain[net, data, MaxTrainingRounds -> 100, TargetDevice -> "CPU"];
trained[1.0]

res = NetTrain[NetChain[{LinearLayer[1]}, "Input" -> 2, "Output" -> "Scalar"],
  Table[RandomReal[1, 2] -> RandomReal[], 200], All, MaxTrainingRounds -> 20];
{res["TrainedNet"], res["LossEvolutionPlot"]}

net = NetChain[{ConvolutionLayer[16, 3], Ramp, PoolingLayer[2, 2]},
  "Input" -> NetEncoder[{"Image", {32, 32}}]];
NetInitialize[net][ExampleData[{"TestImage", "Lena"}]] // Dimensions

net = NetInitialize[NetChain[{LinearLayer[4], Ramp, LinearLayer[2]},
  "Input" -> 3], RandomSeeding -> 1234];
net[{1., 0., -1.}]

net = NetModel["LeNet Trained on MNIST Data"];
features = NetReplacePart[net, "Output" -> None];
NetTake[net, {1, 5}]

net = NetModel["LeNet Trained on MNIST Data"];
feat = NetTake[net, {1, "Ramp"}];
Head[feat]

net = NetChain[{LinearLayer[8], Ramp, LinearLayer[4], SoftmaxLayer[]},
  "Input" -> 3];
NetDrop[net, -1]

net = NetModel["LeNet Trained on MNIST Data"];
test = RandomSample[ExampleData[{"MachineLearning", "MNIST"}, "TestData"], 200];
NetMeasurements[net, test, {"Accuracy", "ConfusionMatrixPlot"}]

cell = NetGraph[{CatenateLayer[], LinearLayer[4], Tanh},
  {{NetPort["Input"], NetPort["State"]} -> 1 -> 2 -> 3 -> NetPort["State"]}];
NetFoldOperator[cell]
